package native

import (
	"reflect"
	"testing"
	"unsafe"
)

// TestStructLayouts pins the layouts generated by the preview.3 header on
// 64-bit platforms. The C and Go sides exchange these structures by pointer;
// a mismatch would corrupt fields instead of producing a clear ABI error.
func TestStructLayouts(t *testing.T) {
	if unsafe.Sizeof(uintptr(0)) != 8 {
		t.Skip("ABI layout is defined for 64-bit targets")
	}

	type layout struct {
		name string
		size uintptr
		offs map[string]uintptr
	}
	checks := []layout{
		{
			name: "IpcBuffer", size: 16,
			offs: map[string]uintptr{"Data": 0, "Len": 8},
		},
		{
			name: "IndexOptions", size: 168,
			offs: map[string]uintptr{
				"Name": 0, "Replace": 8, "WaitTimeoutMS": 16,
				"NumPartitions": 24, "SampleRate": 32, "MaxIterations": 40, "TargetPartitionSize": 48,
				"NumSubVectors": 56, "NumBits": 64, "M": 72, "EfConstruction": 80,
				"DistanceType": 88, "FTSBaseTokenizer": 96, "FTSLanguage": 104,
				"FTSMaxTokenLength": 112, "FTSLowerCase": 120, "FTSStem": 124,
				"FTSRemoveStopWords": 128, "FTSASCIIFolding": 132, "FTSWithPosition": 136,
				"FTSNgramMinLength": 144, "FTSNgramMaxLength": 152, "FTSNgramPrefixOnly": 160,
			},
		},
		{
			name: "IndexInfo", size: 32,
			offs: map[string]uintptr{"Name": 0, "Columns": 8, "NumColumns": 16, "IndexType": 24},
		},
		{
			name: "IndexStats", size: 24,
			offs: map[string]uintptr{"NumIndexedRows": 0, "NumUnindexedRows": 8, "NumIndices": 16},
		},
		{
			name: "IndexStatistics", size: 40,
			offs: map[string]uintptr{"NumIndexedRows": 0, "NumUnindexedRows": 8, "IndexType": 16, "DistanceType": 24, "NumIndices": 32, "HasNumIndices": 36},
		},
		{
			name: "Version", size: 24,
			offs: map[string]uintptr{"Version": 0, "TimestampSeconds": 8, "TimestampNanos": 16},
		},
		{
			name: "VersionMetadata", size: 24,
			offs: map[string]uintptr{"Keys": 0, "Values": 8, "Count": 16},
		},
		{
			name: "Tag", size: 32,
			offs: map[string]uintptr{"Name": 0, "Version": 8, "ManifestSize": 16, "Branch": 24},
		},
		{
			name: "CompactionOptions", size: 56,
			offs: map[string]uintptr{
				"SetFields": 0, "TargetRowsPerFragment": 8, "MaxRowsPerGroup": 16,
				"MaxBytesPerFile": 24, "MaterializeDeletions": 32,
				"MaterializeDeletionsThreshold": 36, "NumThreads": 40, "BatchSize": 48,
			},
		},
		{
			name: "PruneOptions", size: 24,
			offs: map[string]uintptr{"SetFields": 0, "OlderThanNanos": 8, "DeleteUnverified": 16, "ErrorIfTaggedOldVersions": 20},
		},
		{
			name: "OptimizeConfig", size: 88,
			offs: map[string]uintptr{"Action": 0, "Compaction": 8, "Prune": 64},
		},
		{name: "CompactionMetrics", size: 32, offs: map[string]uintptr{}},
		{name: "RemovalStats", size: 16, offs: map[string]uintptr{}},
		{
			name: "OptimizeStats", size: 64,
			offs: map[string]uintptr{"HasCompaction": 0, "Compaction": 8, "HasPrune": 40, "Prune": 48},
		},
		{
			name: "MergeInsertOptions", size: 48,
			offs: map[string]uintptr{
				"WhenMatchedUpdateAll": 0, "WhenMatchedUpdateAllCondition": 8,
				"WhenNotMatchedInsertAll": 16, "WhenNotMatchedBySourceDelete": 20,
				"WhenNotMatchedBySourceDeleteFilter": 24, "UseIndex": 32, "TimeoutMS": 40,
			},
		},
		{
			name: "MergeInsertResultV2", size: 48,
			offs: map[string]uintptr{
				"Version": 0, "NumInsertedRows": 8, "NumUpdatedRows": 16,
				"NumDeletedRows": 24, "NumAttempts": 32, "NumRows": 40,
			},
		},
		{name: "UpdateResult", size: 16, offs: map[string]uintptr{}},
		{name: "DeleteResult", size: 16, offs: map[string]uintptr{}},
		{
			name: "ColumnAlteration", size: 24,
			offs: map[string]uintptr{"Path": 0, "Rename": 8, "SetNullable": 16, "Nullable": 20},
		},
	}

	values := map[string]any{
		"IpcBuffer":           IpcBuffer{},
		"IndexOptions":        IndexOptions{},
		"IndexInfo":           IndexInfo{},
		"IndexStats":          IndexStats{},
		"IndexStatistics":     IndexStatistics{},
		"Version":             Version{},
		"VersionMetadata":     VersionMetadata{},
		"Tag":                 Tag{},
		"CompactionOptions":   CompactionOptions{},
		"PruneOptions":        PruneOptions{},
		"OptimizeConfig":      OptimizeConfig{},
		"CompactionMetrics":   CompactionMetrics{},
		"RemovalStats":        RemovalStats{},
		"OptimizeStats":       OptimizeStats{},
		"MergeInsertOptions":  MergeInsertOptions{},
		"MergeInsertResultV2": MergeInsertResultV2{},
		"UpdateResult":        UpdateResult{},
		"DeleteResult":        DeleteResult{},
		"ColumnAlteration":    ColumnAlteration{},
	}
	for _, check := range checks {
		value, ok := values[check.name]
		if !ok {
			t.Fatalf("missing layout value for %s", check.name)
		}
		typ := reflect.TypeOf(value)
		if typ.Size() != check.size {
			t.Errorf("%s size = %d, want %d", check.name, typ.Size(), check.size)
		}
		for field, want := range check.offs {
			structField, ok := typ.FieldByName(field)
			if !ok {
				t.Errorf("%s has no field %s", check.name, field)
				continue
			}
			if structField.Offset != want {
				t.Errorf("%s.%s offset = %d, want %d", check.name, field, structField.Offset, want)
			}
		}
	}
}
